# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See docs/REPARSE-CONTRACT.md

# Root prefix of an already expanded (absolute) Windows path:
#   'C:\'              for a volume root
#   '\\server\share'   for a UNC share root
#   '\'                for a drive relative rooted path
#   ''                 otherwise (should not happen after GetFullPath)
function Get-WReparsePathRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$FullPath
    )
    if ([string]::IsNullOrEmpty($FullPath)) { return '' }
    if ($FullPath.Length -ge 2 -and $FullPath[0] -eq '\' -and $FullPath[1] -eq '\') {
        # UNC: the root is \\server\share
        $serverEnd = $FullPath.IndexOf('\', 2)
        if ($serverEnd -lt 0) { return $FullPath }
        $shareEnd = $FullPath.IndexOf('\', $serverEnd + 1)
        if ($shareEnd -lt 0) { return $FullPath }
        return $FullPath.Substring(0, $shareEnd)
    }
    if ($FullPath.Length -ge 3 -and $FullPath[1] -eq ':' -and
        ($FullPath[2] -eq '\' -or $FullPath[2] -eq '/')) {
        return $FullPath.Substring(0, 3)
    }
    if ($FullPath[0] -eq '\' -or $FullPath[0] -eq '/') { return '\' }
    return ''
}

# Canonical form used for every comparison and for the report:
#   * full (rooted) path with '.' and '..' collapsed
#   * no trailing directory separator, except for a volume root ('C:\')
#     or a UNC share root ('\\server\share')
#   * original casing preserved (no case folding)
# Throws when the string cannot be turned into a path at all; callers map
# that to the 'invalid_argument' error code.
function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Path
    )
    if ($null -eq $Path) {
        throw 'Cannot canonicalise a null path.'
    }
    $candidate = $Path.Trim()
    if ($candidate.Length -eq 0) {
        throw 'Cannot canonicalise an empty path.'
    }

    # GetFullPath expands to an absolute path and collapses '.' and '..'.
    # It throws for strings that cannot be a path (invalid characters, empty,
    # too long); that is exactly the 'cannot be canonicalised' case.
    $full = [System.IO.Path]::GetFullPath($candidate)
    if ([string]::IsNullOrWhiteSpace($full)) {
        throw "Cannot canonicalise path: $Path"
    }

    $root = Get-WReparsePathRoot -FullPath $full
    if ($root.Length -eq 0) { return $full }
    if ($full.Length -le $root.Length) {
        # volume roots keep their trailing separator, UNC share roots do not
        if ($root.Length -ge 2 -and $root[0] -eq '\' -and $root[1] -eq '\') {
            return $root.TrimEnd('\')
        }
        return $root
    }
    $remainder = $full.Substring($root.Length).TrimEnd('\', '/')
    if ($remainder.Length -eq 0) {
        if ($root.Length -ge 2 -and $root[0] -eq '\' -and $root[1] -eq '\') {
            return $root.TrimEnd('\')
        }
        return $root
    }
    return ($root.TrimEnd('\', '/') + '\' + $remainder)
}

# Directory-boundary aware containment. 'C:\root2' is NOT inside 'C:\root'
# even though 'C:\root2'.StartsWith('C:\root') is true. Windows path
# comparison is case-insensitive, so the ordinal-ignore-case comparer is used
# (never a culture sensitive comparison).
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Path,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) {
        return $false
    }
    $p = $null
    $r = $null
    try { $p = Get-WReparseCanonicalPath -Path $Path } catch { return $false }
    try { $r = Get-WReparseCanonicalPath -Path $Root } catch { return $false }
    if ([string]::IsNullOrEmpty($p) -or [string]::IsNullOrEmpty($r)) { return $false }

    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return $true }

    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    return $p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

# Relative path of a scanned entry with respect to the scan root, using the
# Windows separator. The root itself yields '.'.
function Get-WReparseRelativePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$FullPath,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root
    )
    $p = Get-WReparseCanonicalPath -Path $FullPath
    $r = Get-WReparseCanonicalPath -Path $Root
    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return '.' }
    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    if ($p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $p.Substring($prefix.Length)
    }
    return $p
}

# The reparse target stored on disk may be relative. A relative target is
# resolved against the directory that CONTAINS the link, never against the
# process working directory and never against the scan root. Returns $null
# when there is no target or when it cannot be canonicalised.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$LinkFullPath,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }

    $raw = $RawTarget.Trim()
    if ($raw.Length -eq 0) { return $null }

    # Strip the NT namespace prefixes a reparse buffer may still carry.
    if ($raw.StartsWith('\??\')) { $raw = $raw.Substring(4) }
    elseif ($raw.StartsWith('\\?\")) { $raw = $raw.Substring(4) }
    $raw = $raw.TrimEnd('\')
    if ($raw.Length -eq 0) { return $null }

    $linkPath = $LinkFullPath
    try { $linkPath = Get-WReparseCanonicalPath -Path $LinkFullPath } catch { $linkPath = $LinkFullPath }
    $linkDirectory = [System.IO.Path]::GetDirectoryName($linkPath)
    if ([string]::IsNullOrEmpty($linkDirectory)) {
        $linkDirectory = [System.IO.Path]::GetPathRoot($linkPath)
    }
    if ([string]::IsNullOrEmpty($linkDirectory)) { return $null }

    $candidate = $null
    if ($raw.Length -ge 2 -and $raw[0] -eq '\' -and $raw[1] -eq '\') {
        # UNC target: already fully qualified.
        $candidate = $raw
    }
